test_suite:
function mountObserved() {
  const state: { width?: number; height?: number } = {};
  function Target() {
    const { ref, width, height } = useResizeObserver();
    state.width = width;
    state.height = height;
    return <div ref={ref as any} />;
  }
  const view = render(<Target />);
  return { state, el: view.container.firstChild, unmount: view.unmount };
}

function stubObserver() {
  const observer = { cb: undefined as any, observe: vi.fn(), disconnect: vi.fn() };
  vi.stubGlobal('ResizeObserver', vi.fn((fn: ResizeObserverCallback) => {
    observer.cb = fn;
    return { observe: observer.observe, disconnect: observer.disconnect };
  }));
  return observer;
}

afterEach(() => {
  vi.unstubAllGlobals();
});

test('returns initial width and height of 0', () => {
  const { result } = renderHook(() => useResizeObserver());
  expect(result.current.width).toBe(0);
  expect(result.current.height).toBe(0);
});

test('returns a ref object', () => {
  const { result } = renderHook(() => useResizeObserver());
  expect(result.current.ref).toHaveProperty('current');
});

test('observes the attached element', () => {
  const observer = stubObserver();
  const { el } = mountObserved();
  expect(observer.observe).toHaveBeenCalledWith(el);
});

test('updates size from ResizeObserver entry', () => {
  const observer = stubObserver();
  const { state } = mountObserved();
  act(() => observer.cb([{ contentRect: { width: 300, height: 150 } }], {}));
  expect(state.width).toBe(300);
  expect(state.height).toBe(150);
});

// __hidden__
test('disconnects observer on unmount', () => {
  const observer = stubObserver();
  const { unmount } = mountObserved();
  unmount();
  expect(observer.disconnect).toHaveBeenCalled();
});

solution:
import { useRef, useState, useEffect } from 'react';

export function useResizeObserver() {
  const ref = useRef<HTMLElement>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      setSize({ width, height });
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return { ref, width: size.width, height: size.height };
}
